window.POETRY_REGISTER("v5-strict-13-11-0-edefa1fb8e7f.js",{"poems":[[53537,2],[155919,7],[260441,7],[265404,7],[271951,7],[285959,7],[288132,7],[288143,7],[319441,7],[321247,7],[325283,7],[331771,7],[340166,9],[378268,10],[395378,13],[398167,13],[413917,8],[473778,8],[581857,8],[650074,5],[672655,5],[706935,5]],"pairs":[["窃疑何二娘何氏女何仙乃一人","即世俗八仙中之何仙姑也",0],["惟闻孔子之殁一百年而生孟子","释迦之寂二千岁而有禅师",1],["丰城地下掘起龙泉太阿双宝剑","南山雾里窥见隠豹文章皮",2],["繄四海以为家兮何独困此一方","视己同溺兮用造舟以为梁",3],["方其作元舅之碑以伸天子之孝","拒佞幸之请而杜亵取之门",4],["武夷君去后兮有十三仙之同时","代不乏人之兮仙阶陆续跻",5],["视万马之奔逸兮歛组辔而独驻","安于一实兮岂斯世之足语",6],["孑不群而介立兮众嚣嚣而肆呵","玄虬蹶泥兮浸雄虹于颓波",7],["忽修灵之聿皇兮任侏儒之傞傞","咎将谁执兮岂天赋之未薖",7],["今年舍我去者二百二十有五日","今日之后谁使来日来相催",8],["吾闻狄公焚烧江南一千七百所","只留夏禹泰伯季札伍子胥",9],["又进而歌曰壮士一去兮不复还","不意咸阳殿上有柱尚可环",10],["虽然吾不愿子以之属文如曹刘","吾不愿子以之奏赋如枚邹",11],["润泽善利责望水兴云作雨嘑噏","燥湿申命林麓原隰诸林丘",12],["我知山灵川后今岁效职致丰稔","不负天子圣虑贻我使者羞",12],["但见一龙盘空偃蹇飞下尾闾穴","一龙搅海奋迅直上青天衢",13],["吾闻狄公焚烧江南一千七百所","只留夏禹泰伯季札伍子胥",14],["今年舍我去者二百二十有五日","今日之后谁使来日来相催",15],["胡为乎六龙斜飞于若木之金天","复沈沦于西溟澒洞之重渊",16],["神农以还九千九百九十有馀帝","扬雷掣电纷纷跨鹤而来迎",17],["但恐勿乐有喜鹤书飞来自天上","东山谢老未许独乐忘生民",18],["眼看着晋家的江山又打个两起","不多时把个刀把给了刘聪",19],["剑乎剑乎汝不自言可以托生死","安知人不视作钝铁与顽铜",20],["下有黑狮白虎踆踆踠踠伏阙下","上有琼楼玉宇高处天风寒",21]]});
